-- Stores a patch inside an instrument's comment lines, so the patch travels
-- with the song and with exported .xrni instruments.
--
--   #JSNP-BEGIN v=1 uid=0a1b2c3d4e5f (generated by JussiSnupps ...)
--   |{"audio":[...],...|
--   |...continued JSON...|
--   #JSNP-END
--
-- Each JSON chunk is wrapped in '|' so trimming of whitespace at line ends
-- can't eat spaces inside the JSON. Lines outside the block are the user's
-- own comments and are kept as they are.

local json = require "jsnp.util.json"
local Patch = require "jsnp.model.patch"

local Serialize = {}

Serialize.BEGIN = "#JSNP-BEGIN"
Serialize.END = "#JSNP-END"
Serialize.CHUNK = 180

function Serialize.encode(p)
  return json.encode(p)
end

local function migrate(t)
  -- Only version 1 exists so far. Future versions upgrade `t` here, step by
  -- step, before validation.
  if type(t.v) ~= "number" then
    return nil, "patch has no version"
  end
  if t.v > Patch.VERSION then
    return nil, "patch was made by a newer JussiSnupps (format v" .. t.v .. ")"
  end
  return t
end

-- Decodes a JSON string into a validated patch. Returns patch, warnings
-- or nil, error.
function Serialize.decode(str, filter_types)
  local ok, t = pcall(json.decode, str)
  if not ok then
    return nil, "corrupt patch data (" .. tostring(t) .. ")"
  end
  if type(t) ~= "table" then
    return nil, "patch data is not an object"
  end
  local m, err = migrate(t)
  if not m then
    return nil, err
  end
  return Patch.validate(m, filter_types)
end

local function is_begin(line)
  return type(line) == "string" and line:sub(1, #Serialize.BEGIN) == Serialize.BEGIN
end

local function is_end(line)
  return type(line) == "string" and line:sub(1, #Serialize.END) == Serialize.END
end

-- Returns the comment lines without the patch block.
function Serialize.strip_block(lines)
  local out = {}
  local inside = false
  for _, line in ipairs(lines or {}) do
    if is_begin(line) then
      inside = true
    elseif inside then
      if is_end(line) then inside = false end
    else
      out[#out + 1] = line
    end
  end
  -- drop trailing empty lines left behind by an old block
  while #out > 0 and out[#out]:match("^%s*$") do
    out[#out] = nil
  end
  return out
end

function Serialize.read_header(lines)
  for _, line in ipairs(lines or {}) do
    if is_begin(line) then
      local v = tonumber(line:match("v=(%d+)"))
      local uid = line:match("uid=([%w]+)")
      return { v = v, uid = uid }
    end
  end
  return nil
end

-- New comment lines: the user's lines, then the patch block.
function Serialize.to_lines(p, existing_lines)
  local out = Serialize.strip_block(existing_lines)
  if #out > 0 then
    out[#out + 1] = ""
  end
  out[#out + 1] = string.format(
    "%s v=%d uid=%s (generated by JussiSnupps - edit it with Tools > JussiSnupps)",
    Serialize.BEGIN, Patch.VERSION, p.uid)
  local s = Serialize.encode(p)
  for i = 1, #s, Serialize.CHUNK do
    out[#out + 1] = "|" .. s:sub(i, i + Serialize.CHUNK - 1) .. "|"
  end
  out[#out + 1] = Serialize.END
  return out
end

-- Reads the patch back from comment lines. Returns patch, warnings or
-- nil, error.
function Serialize.from_lines(lines, filter_types)
  local chunks = {}
  local inside, found, closed = false, false, false
  for _, line in ipairs(lines or {}) do
    if is_begin(line) then
      inside, found = true, true
      chunks = {}
    elseif inside then
      if is_end(line) then
        inside, closed = false, true
        break
      end
      local body = line:match("^%s*|(.*)|%s*$")
      if body == nil then
        return nil, "patch block has a damaged line"
      end
      chunks[#chunks + 1] = body
    end
  end
  if not found then
    return nil, "no JussiSnupps patch in this instrument"
  end
  if not closed then
    return nil, "patch block is incomplete"
  end
  return Serialize.decode(table.concat(chunks), filter_types)
end

return Serialize
